import type { ReactNode } from 'react';
import { ArrowDown, ArrowUp, ArrowUpDown } from 'lucide-react';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Skeleton } from '@/components/ui/skeleton';
import { cn } from '@/lib/utils';
import { EmptyState } from './EmptyState';

export type DataTableAlign = 'left' | 'right' | 'center';
export type DataTableDensity = 'standard' | 'compact';
export type SortDirection = 'asc' | 'desc';

/** 排序状态：columnKey 对应列的 key；清空排序时整个对象置 null */
export interface DataTableSort {
  columnKey: string;
  direction: SortDirection;
}

export interface DataTableColumn<Row> {
  /** 列标识：同时作为表头 key 与排序关联键 */
  key: string;
  header: ReactNode;
  cell: (row: Row) => ReactNode;
  /** 对齐（S-29：文本左、数字右、操作右）；默认 left */
  align?: DataTableAlign;
  /** 列宽/最小宽等附加类（如 'w-24'、'min-w-40'），同时作用于表头与单元格 */
  className?: string;
  /** 声明可排序：表头渲染排序按钮与三态箭头（排序逻辑由调用方落地） */
  sortable?: boolean;
}

interface DataTableProps<Row> {
  columns: DataTableColumn<Row>[];
  rows: Row[];
  rowKey: (row: Row) => string;
  loading?: boolean;
  /** 骨架行数（S-08：加载时保留表格结构与列宽，避免布局跳动）；默认 8 */
  loadingRowCount?: number;
  /** 空态插槽；缺省渲染中性「暂无数据」。四种语义（无数据/筛选无结果/无权限/失败）由调用方选文案 */
  empty?: ReactNode;
  /** 当前排序（受控）；仅作指示与上抛，不内置排序算法 */
  sort?: DataTableSort | null;
  onSortChange?: (sort: DataTableSort | null) => void;
  /** 行密度（S-29）：standard 60px（默认，列表页）/ compact 46px（审计、日志） */
  density?: DataTableDensity;
  /** 行操作区：提供时在末尾追加固定「操作」列；无权限时传 undefined 即不渲染该列 */
  rowActions?: (row: Row) => ReactNode;
  rowActionsHeader?: ReactNode;
  rowActionsClassName?: string;
}

const ALIGN_CLASS: Record<DataTableAlign, string> = {
  left: 'text-left',
  right: 'text-right',
  center: 'text-center',
};

const DENSITY_ROW_CLASS = {
  standard: 'h-15',
  compact: 'h-[46px]',
} as const;

/**
 * 列定义驱动的数据表格（S-02 用户列表 / S-29 表格基座）：
 * 表头 40px 吸顶、正文 13px、骨架行保留列结构；与 Pagination 分开使用（分页由页面组合）。
 */
export function DataTable<Row>({
  columns,
  rows,
  rowKey,
  loading = false,
  loadingRowCount = 8,
  empty,
  sort,
  onSortChange,
  density = 'standard',
  rowActions,
  rowActionsHeader = '操作',
  rowActionsClassName = 'w-24',
}: DataTableProps<Row>) {
  const columnCount = columns.length + (rowActions ? 1 : 0);
  const rowClass = DENSITY_ROW_CLASS[density];
  const cellClass = 'px-3 first:pl-4 last:pr-4';

  const cycleSort = (columnKey: string): DataTableSort | null => {
    if (sort?.columnKey === columnKey) {
      return sort.direction === 'asc' ? { columnKey, direction: 'desc' } : null;
    }
    return { columnKey, direction: 'asc' };
  };

  return (
    <div className="rounded-lg border">
      {/* table-fixed：列宽由表头 className 决定而非内容撑开，保证与设计稿列分布一致 */}
      <Table className="table-fixed text-base">
        <TableHeader>
          <TableRow className="hover:bg-transparent">
            {columns.map((column) => {
              const active = sort?.columnKey === column.key ? sort.direction : null;
              const alignClass = ALIGN_CLASS[column.align ?? 'left'];
              return (
                <TableHead
                  key={column.key}
                  scope="col"
                  aria-sort={
                    column.sortable
                      ? active === 'asc'
                        ? 'ascending'
                        : active === 'desc'
                          ? 'descending'
                          : 'none'
                      : undefined
                  }
                  className={cn(
                    'sticky top-0 z-10 h-10 bg-secondary px-3 text-sm font-medium first:pl-4 last:pr-4',
                    alignClass,
                    column.className,
                  )}
                >
                  {column.sortable && onSortChange ? (
                    <button
                      type="button"
                      className="inline-flex items-center gap-1 hover:text-foreground"
                      onClick={() => onSortChange(cycleSort(column.key))}
                    >
                      {column.header}
                      {active === 'asc' ? (
                        <ArrowUp className="h-3 w-3" aria-hidden />
                      ) : active === 'desc' ? (
                        <ArrowDown className="h-3 w-3" aria-hidden />
                      ) : (
                        <ArrowUpDown className="h-3 w-3 text-ring" aria-hidden />
                      )}
                    </button>
                  ) : (
                    column.header
                  )}
                </TableHead>
              );
            })}
            {rowActions ? (
              <TableHead
                scope="col"
                className={cn(
                  'sticky top-0 z-10 h-10 bg-secondary px-3 pr-4 text-right text-sm font-medium',
                  rowActionsClassName,
                )}
              >
                {rowActionsHeader}
              </TableHead>
            ) : null}
          </TableRow>
        </TableHeader>
        <TableBody>
          {loading ? (
            Array.from({ length: loadingRowCount }, (_, rowIndex) => (
              <TableRow key={`skeleton-${rowIndex}`} className={rowClass}>
                {columns.map((column, columnIndex) => (
                  <TableCell
                    key={column.key}
                    className={cn(cellClass, ALIGN_CLASS[column.align ?? 'left'], column.className)}
                  >
                    <Skeleton className={columnIndex === 0 ? 'h-4 w-4/5' : 'h-4 w-full'} />
                  </TableCell>
                ))}
                {rowActions ? (
                  <TableCell key="actions" className={cn(cellClass, 'text-right', rowActionsClassName)}>
                    <Skeleton className="ml-auto h-4 w-6" />
                  </TableCell>
                ) : null}
              </TableRow>
            ))
          ) : rows.length === 0 ? (
            <TableRow className="hover:bg-transparent">
              <TableCell colSpan={columnCount} className="p-0">
                {empty ?? <EmptyState title="暂无数据" />}
              </TableCell>
            </TableRow>
          ) : (
            rows.map((row) => (
              <TableRow key={rowKey(row)} className={rowClass}>
                {columns.map((column) => (
                  <TableCell
                    key={column.key}
                    className={cn(cellClass, ALIGN_CLASS[column.align ?? 'left'], column.className)}
                  >
                    {column.cell(row)}
                  </TableCell>
                ))}
                {rowActions ? (
                  <TableCell key="actions" className={cn(cellClass, 'text-right', rowActionsClassName)}>
                    {rowActions(row)}
                  </TableCell>
                ) : null}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  );
}
